"""Canonical space-leaf traversal for a bookable-room catalog.

A space is bookable exactly when it is reachable from an event through the
Contains relationship and has no child spaces.  The walker is the canonical
definition, so unreachable spaces are not accidentally treated as rooms by a
set-difference calculation.
"""

node Event {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Space {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains {
    has position: int = 0;
}

walker LeafCatalog {
    has leaf_count: int = 0;
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_event with Event entry {
        print(f"Cataloging event: {here.title}");
        visit [->:Contains:->] else {
            print("event has no spaces");
        }
    }

    can inspect_space with Space entry {
        if self.depth >= self.max_depth {
            print(f"depth limit reached near {here.title}");
            disengage;
        } else {
            self.depth += 1;
            visit [->:Contains:->] else {
                self.leaf_count += 1;
                print(f"bookable room: {here.title}");
            }
            self.depth -= 1;
        }
    }

    can report with Root exit {
        print(f"canonical bookable-room count: {self.leaf_count}");
    }
}

with entry {
    event = Event(title="Autumn Games", year=2025);

    hall = Space(title="Main Hall", available=True);
    studio = Space(title="Studio", available=True);
    room_a = Space(title="Room A", available=True);
    room_b = Space(title="Room B", available=True);
    storage = Space(title="Storage", available=False);

    external_event = Event(title="Unrelated Event", year=2025);
    misplaced = Space(title="Misplaced Space", available=True);

    root --> event;
    root --> external_event;

    event +>:Contains(position=1):+> hall;
    hall +>:Contains(position=1):+> studio;
    hall +>:Contains(position=2):+> room_a;
    studio +>:Contains(position=1):+> room_b;
    event +>:Contains(position=2):+> storage;

    external_event +>:Contains(position=1):+> misplaced;

    root spawn LeafCatalog(max_depth=32);
}

