"""Canonical bookable-room traversal for a scoped space tree.

The event-to-space and parent-to-child relationships are represented by typed
edges.  Bookable rooms are the terminal spaces reached from the event root,
while an incorrectly scoped space attached under a different event is ignored.
An explicit visited list preserves cycle safety because walkers do not dedupe
nodes automatically.
"""

node Event {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Space {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has event_key: str = "";
    has order: int = 0;
    has is_leaf: bool = False;
}

edge Contains {
    has order: int = 0;
}

walker BookableRooms {
    has event_key: str = "";
    has seen: list[str] = [];
    has leaves: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with Event entry {
        if self.event_key == "" {
            self.event_key = here.title;
        }
        print(f"Scanning spaces for {self.event_key}");
        visit [->:Contains:->];
    }

    can inspect with Space entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.seen.append(here.title);
            if here.event_key == self.event_key {
                if here.is_leaf {
                    self.leaves.append(here.title);
                    print(f"bookable room: {here.title}");
                }
            }
            visit [->:Contains:->];
        }
    }

    can report with Root exit {
        print(f"canonical room count: {len(self.leaves)}");
    }
}

