    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Module {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

walker TotalityChecker {
    has seen: list[str] = [];
    has checked: int = 0;
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Starting totality and effect-freedom analysis");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Definition entry {
        if here.title in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}; analysis stopped");
            disengage;
        } else {
            self.seen.append(here.title);
            self.checked += 1;
            print(f"checked pure definition: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

