        year=2024,
        available=True
    );

    root --> compiler;
    compiler +>:DependsOn(reason="parses source"):+> parser;
    compiler +>:DependsOn(reason="proves checked definitions"):+> checker;
    checker +>:DependsOn(reason="evaluates pure expressions"):+> evaluator;
    evaluator +>:DependsOn(reason="uses compiler interfaces"):+> compiler;

    auditor = TotalityChecker();
    root spawn auditor;

    print(f"definitions checked: {auditor.checked}");
    print(f"cycle found: {auditor.cycle_found}");
}

