"""Native Jac demo of totality and effect-freedom auditing over dependencies."""

node Module {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Definition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has total: bool = True;
    has pure: bool = True;
    has effect_row: str = "";
}

edge Contains { }

edge Depends {
    has reason: str = "";
}

walker TotalityAuditor {
    has seen: list[str] = [];
    has invalid_count: int = 0;
    has cycle_count: int = 0;

    can begin with Root entry {
        print("Auditing definitions for totality and effect freedom");
        visit [-->] else {
            disengage;
        }
    }

    can enter_module with Module entry {
        print(f"Module: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_definition with Definition entry {
        if here.title in self.seen {
            self.cycle_count += 1;
            here.available = False;
            print(f"[cycle] dependency revisit at {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);

            if here.total == False {
                self.invalid_count += 1;
                here.available = False;
                print(f"[reject] {here.title}: no termination proof");
            }

            if here.pure == False {
                self.invalid_count += 1;
                here.available = False;
                print(f"[reject] {here.title}: effect row is {here.effect_row}");
            }

            if here.total and here.pure {
                print(f"[accept] {here.title}: total and effect-free");
            }

            visit [->:Depends:->] else {
                disengage;
            }
        }
    }
}

