"""Offline DEV winner selection with typed review links and explicit cycle detection."""

node Review {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Candidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has structural_bps: int = 0;
    has downstream_bps: int = 0;
    has global_regression_bps: int = 0;
    has hallucination_delta: int = 0;
    has gates_passed: bool = False;
    has priority: int = 0;
    has frozen: bool = False;

    def qualifies() -> bool {
        return self.available
            and self.structural_bps >= 500
            and self.downstream_bps > 0
            and self.global_regression_bps <= 100
            and self.hallucination_delta == 0
            and self.gates_passed;
    }

    def score() -> int {
        return self.structural_bps + self.downstream_bps;
    }
}

edge Evaluates {
    has purpose: str = "";
}

edge CandidateLink {
    has reason: str = "";
}

walker OrderAuditor {
    has seen: list[str] = [];
    has winner_title: str = "";
    has best_score: int = -1;
    has best_priority: int = 2147483647;
    has frozen: bool = False;

    can start with Root entry {
        print("Auditing offline DEV candidates");
        visit [->:Evaluates:->] else {
            disengage;
        }
    }

    can inspect with Review entry {
        print(f"Reviewing {here.title}");
        visit [->:Evaluates:->] else {
            disengage;
        }
    }

    can inspect with Candidate entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; branch ignored");
        } else {
            self.seen.append(here.title);

            if here.qualifies() {
                candidate_score = here.score();
                better_score = candidate_score > self.best_score;
                equal_score = candidate_score == self.best_score;
                better_tie = equal_score
                    and here.priority < self.best_priority;

                if better_score or better_tie {
                    self.winner_title = here.title;
                    self.best_score = candidate_score;
                    self.best_priority = here.priority;
                    print(f"eligible candidate: {here.title}");
                }
            } else {
                print(f"rejected candidate: {here.title}");
            }

            visit [->:CandidateLink:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        if self.winner_title == "" {
            print("NO_REPAIR_ROUTE");
        } else {
            self.frozen = True;
            print(f"frozen HOLDOUT finalist: {self.winner_title}");
        }
    }
}

