"""Depth-guarded rendering graph for recursive Form XObjects and tiling patterns."""

node Renderable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Form(Renderable) {
    has subtype: str = "Form";
}

node TilingPattern(Renderable) {
    has subtype: str = "TilingPattern";
}

edge Contains { }

edge Paints {
    has operation: str = "paint";
}

walker RenderGuard {
    has depth: int = 0;
    has depth_limit: int = 6;

    can begin with Root entry {
        print("begin guarded render");
        visit [->:Contains:->] else {
            print("render graph is empty");
            disengage;
        }
    }

    can render with Form | TilingPattern entry {
        self.depth = self.depth + 1;

        if self.depth >= self.depth_limit {
            print(f"depth limit reached at {here.title}");
            disengage;
        } else {
            print(f"rendering {here.title} at depth {self.depth}");
            visit [->:Paints:->] else {
                print(f"finished {here.title}");
                disengage;
            }
        }
    }

    can unwind with Form | TilingPattern exit {
        next_depth = self.depth - 1;
        self.depth = next_depth;
    }
}

with entry {
    form_self = Form(title="FmSelf");
    form_a = Form(title="Fm0");
    form_b = Form(title="Fm1");
    pattern_self = TilingPattern(title="PatternSelf");

    root +>:Contains:+> form_self;
    root +>:Contains:+> form_a;
    root +>:Contains:+> pattern_self;

    form_self +>:Paints(operation="Do FmSelf"):+> form_self;
    form_a +>:Paints(operation="Do Fm1"):+> form_b;
    form_b +>:Paints(operation="Do Fm0"):+> form_a;
    pattern_self +>:Paints(operation="fill with PatternSelf"):+> pattern_self;

    root spawn RenderGuard(depth_limit=6);
}

