    def validate(schema_version: str) -> bool {
        return schema_version == self.expected_schema;
    }
}

node AuditRecord {
    has audit_id: str = "";
    has outcome: str = "PENDING";
    has message: str = "";
}

edge Ingests {
}

edge ContainsBatch {
}

edge RequiresContract {
}

edge RecordsAudit {
}

walker BronzeIngest {
    has batch_schema: str = "";
    has job_status: str = "RUNNING";
    has failure_message: str = "";

    can start with Root entry {
        print("Bronze ingestion started");
        visit [->:Ingests:->] else {
            disengage;
        }
    }

    can load_batch with PipelineRun entry {
        here.status = "RUNNING";
        visit [->:ContainsBatch:->] else {
            self.job_status = "FAILED";
            self.failure_message = "No batch was supplied";
            disengage;
        }
    }

    can validate_batch with Batch entry {
        self.batch_schema = here.schema_version;
        here.valid = here.schema_version == "bronze-v1";

        if here.valid {
            print(f"Batch {here.batch_id} passed preliminary bronze checks");
        } else {
            print(f"Batch {here.batch_id} violated the bronze data contract");
        }

        visit [->:RequiresContract:->] else {
            self.job_status = "FAILED";
            self.failure_message = "Contract definition was unavailable";
            disengage;
        }
    }

    can enforce_contract with DataContract entry {
        if here.validate(self.batch_schema) {
            self.job_status = "SUCCESS";
            self.failure_message = "Contract validation passed";
        } else {
            self.job_status = "FAILED";
            self.failure_message = "Contract violation quarantined at bronze entry";
        }

        visit [->:RecordsAudit:->] else {
            disengage;
        }
    }

    can record_result with AuditRecord entry {
        here.outcome = self.job_status;
        here.message = self.failure_message;

        print(f"Databricks job status: {self.job_status}");
        print(f"Audit {here.audit_id}: {here.outcome} - {here.message}");
    }
}

