    has top_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can load_today with Today entry {
        calendar_state = "ready" if here.calendar_available else "unavailable";
        retainer_state = "ready" if here.retainer_available else "unavailable";

        print(f"Today: {here.title}");
        print(f"Calendar {here.selected_calendar}: {calendar_state}, "
              f"freshness={here.calendar_freshness}, "
              f"reconnect={here.reconnect_state}");
