        if here.busy_only {
            print(f"Agenda busy block: {here.starts_at} "
                  f"(provider details hidden)");
        } else {
            print(f"Agenda: {here.title} at {here.starts_at} "
                  f"on {here.calendar_name}, provider={here.provider}");
        }
