        if here.due_days < 0 {
            print(f"Retainer overdue: {here.title} for {here.client}");
        } else {
            if here.due_days <= 3 {
                print(f"Retainer due soon: {here.title} for {here.client} "
                      f"in {here.due_days} day(s)");
            } else {
                print(f"Retainer scheduled: {here.title} for {here.client} "
                      f"in {here.due_days} day(s)");
            }
        }

        if here.carried_over {
            print(f"Retainer carried over: {here.title}");
        }

        if (here.carried_over or here.due_days <= 3) and self.top_count < 3 {
            self.top_count += 1;
            print(f"Top {self.top_count}: retainer deliverable "
                  f"{here.title}");
        }
    }
}

