node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has doc_id: str = "";
}

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has page_id: str = "";
}

node Character {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has glyph: str = "";
    has position: int = 0;
}

node Font {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has font_id: str = "";
    has decoded_for: str = "";
}

edge HasPage { }
edge Contains { }
edge UsesFont { }

walker Extractor {
    has seen_ids: list[str] = [];
    has active_doc: str = "";
    has output: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_document with Document entry {
        if here.doc_id in self.seen_ids {
            print(f"cycle guard: skipped document {here.doc_id}");
        } else {
            self.seen_ids.append(here.doc_id);
            self.active_doc = here.doc_id;
            print(f"extracting {here.title}");

            visit [->:HasPage:->] else {
                disengage;
            }

            visit [->:UsesFont:->] else {
                disengage;
            }
        }
    }

    can inspect_page with Page entry {
        print(f"visiting page {here.page_id}");

        visit [->:Contains:->] else {
            disengage;
        }
    }

    can decode_font with Font entry {
        if here.decoded_for != "" and here.decoded_for != self.active_doc {
            print(
                f"cache contamination: {here.font_id} was decoded for "
                f"{here.decoded_for}, now used by {self.active_doc}"
            );
        }

        here.decoded_for = self.active_doc;
    }

    can collect_character with Character entry {
        self.output.append(here.glyph);
        print(f"character {here.position}: {here.glyph}");
    }
}

