"""Foley asset identity demo: duplicate filenames remain distinct through restore and playback."""

node Project {
    has title: str = "";
    has selected_asset_id: str = "";
}

node ProjectAsset {
    has asset_id: str = "";
    has filename: str = "";
    has materialized_path: str = "";
    has available: bool = True;
}

node FoleyClip {
    has title: str = "";
    has project_asset_id: str = "";
    has trim_start: float = 0.0;
    has trim_end: float = 0.0;
    has gain: float = 1.0;
    has fade_in: float = 0.0;
    has fade_out: float = 0.0;
    has reverse: bool = False;
    has normalize: bool = False;
}

edge ProjectAssetLink {
    has role: str = "";
}

edge PlacedClipLink {
    has placement: str = "";
}

walker FoleyRestorer {
    has selected_asset_id: str = "";
    has current_asset_id: str = "";
    has current_filename: str = "";
    has current_path: str = "";
    has restored_count: int = 0;

    can begin with Root entry {
        print("Opening Foley project");
        visit [-->];
    }

    can restore_project with Project entry {
        self.selected_asset_id = here.selected_asset_id;
        print(f"Restoring selected asset identity {self.selected_asset_id}");
        visit [->:ProjectAssetLink:->];
    }

    can materialize_asset with ProjectAsset entry {
        self.current_asset_id = here.asset_id;
        self.current_filename = here.filename;
        self.current_path = here.materialized_path;

        if here.asset_id == self.selected_asset_id {
            print(f"Materialized {here.asset_id} from {here.materialized_path}");
        } else {
            print(f"Skipping unselected asset {here.asset_id}");
        }

        visit [->:PlacedClipLink:->];
    }

    can restore_clip with FoleyClip entry {
        if here.project_asset_id == self.current_asset_id {
            self.restored_count += 1;
            print(
                f"Playing {here.title} from asset {self.current_asset_id} "
                f"({self.current_filename}) at {self.current_path}; "
                f"trim={here.trim_start}-{here.trim_end}, gain={here.gain}, "
                f"fade={here.fade_in}/{here.fade_out}, "
                f"reverse={here.reverse}, normalize={here.normalize}"
            );
        } else {
            print(
                f"Skipped {here.title}: identity {here.project_asset_id} "
                f"does not match selected asset {self.current_asset_id}"
            );
        }
    }

    can report with Root exit {
        print(f"Restored {self.restored_count} Foley clip(s) by project asset identity");
    }
}

