"""Artifact publication audit with typed lineage, corruption rejection, and cycle detection."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has checksum: str = "";
    has version: int = 0;
    has accepted: bool = False;
    has format: str = "";
}

node SourceModel(Artifact) {
}

node CandidateArtifact(Artifact) {
}

node PublishedArtifact(Artifact) {
}

edge Lineage {
    has relation: str = "";
}

walker ArtifactAuditor {
    has seen: list[str] = [];

    can start with Root entry {
        print("Starting artifact lineage audit");
        visit [->:Lineage:->] else {
            disengage;
        }
    }

    can inspect with SourceModel | CandidateArtifact | PublishedArtifact entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping this branch");
            disengage;
        } else {
            self.seen.append(here.title);

            if here.available {
                print(f"valid artifact: {here.title}, checksum={here.checksum}");
            } else {
                here.accepted = False;
                print(f"corrupt or interrupted artifact rejected: {here.title}");
            }

            visit [->:Lineage:->] else {
                print(f"lineage complete at {here.title}");
                disengage;
            }
        }
    }
}

