"""Model checkpoint lineage and surgeon compatibility audit with cycle and boundary guards."""

node ModelCheckpoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identifier: str = "";
    has architecture: str = "";
    has state_version: int = 0;
    has features: list[str] = [];
    has supported_operations: list[str] = [];
    has codec: str = "fp32";
    has hardware: str = "";
    has alias_of: str = "";
    has held_out: bool = False;
}

node SurgeonBundle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bundle_id: str = "";
    has required_architecture: str = "";
    has required_state_version: int = 0;
    has required_feature: str = "";
    has required_operation: str = "";
    has required_hardware: str = "";
}

edge DerivedFrom {
    has relation: str = "ancestry";
}

edge Evaluates {
    has revision: str = "";
}

walker LineageAuditor {
    has seen: list[str] = [];
    has required_architecture: str = "";
    has required_state_version: int = 0;
    has required_feature: str = "";
    has required_operation: str = "";
    has required_hardware: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_bundle with SurgeonBundle entry {
        self.required_architecture = here.required_architecture;
        self.required_state_version = here.required_state_version;
        self.required_feature = here.required_feature;
        self.required_operation = here.required_operation;
        self.required_hardware = here.required_hardware;
        print(f"auditing bundle {here.bundle_id}");
        visit [->:Evaluates:->] else {
            disengage;
        }
    }

    can inspect_checkpoint with ModelCheckpoint entry {
        if here.held_out {
            if here.alias_of != "" {
                print(f"unsupported {here.identifier}: held-out ancestry alias {here.alias_of}");
                disengage;
            }
        }

        if here.identifier in self.seen {
            print(f"failed {here.identifier}: ancestry cycle detected");
            disengage;
        } else {
            self.seen.append(here.identifier);

            outcome = "exact";
            reason = "all architecture, state, feature, operation, codec, and hardware checks passed";

            if here.architecture != self.required_architecture {
                outcome = "unsupported";
                reason = "architecture capability mismatch";
            } elif here.state_version != self.required_state_version {
                outcome = "unsupported";
                reason = "state-version mismatch";
            } elif self.required_feature not in here.features {
                outcome = "unsupported";
                reason = "required feature is missing";
            } elif self.required_operation not in here.supported_operations {
                outcome = "unsupported";
                reason = "required operation is unsupported";
            } elif here.hardware != self.required_hardware {
                outcome = "unsupported";
                reason = "hardware requirement is not met";
            } elif here.codec == "int8" {
                outcome = "adaptable";
                reason = "quantized codec requires an explicit adaptation step";
            } elif here.codec != "fp32" {
                outcome = "unsupported";
                reason = "codec is not supported by this surgeon";
            }

            print(f"{here.identifier}: {outcome}; reason={reason}");
            visit [->:DerivedFrom:->] else {
                disengage;
            }
        }
    }
}

