"""Symlink-aware skill audit modeled with typed graph traversal and cycle guards."""

node Skill {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has real_path: str = "";
    has stale: bool = False;
}

node SkillDirectory(Skill) {
    has entry_kind: str = "directory";
}

node SkillDocument(Skill) {
    has entry_kind: str = "file";
}

node Symlink(Skill) {
    has entry_kind: str = "symlink";
}

edge Contains {
    has relation: str = "contains";
}

edge Resolves {
    has relation: str = "resolves";
}

walker SkillAuditor {
    has visited_realpaths: list[str] = [];
    has checked: int = 0;
    has clean: int = 0;
    has stale_count: int = 0;
    has followed_links: int = 0;

    can start with Root entry {
        print("Starting symlink-aware skill audit");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan_directory with SkillDirectory entry {
        if here.real_path in self.visited_realpaths {
            print(f"[CYCLE] already visited {here.real_path}");
            disengage;
        } else {
            self.visited_realpaths.append(here.real_path);
            print(f"[DIR]  {here.real_path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can follow_symlink with Symlink entry {
        if here.real_path in self.visited_realpaths {
            print(f"[CYCLE] already visited {here.real_path}");
            disengage;
        } else {
            self.visited_realpaths.append(here.real_path);
            self.followed_links += 1;
            print(f"[LINK] {here.real_path} -> resolved target");
            visit [->:Resolves:->] else {
                disengage;
            }
        }
    }

    can inspect_skill with SkillDocument entry {
        if here.real_path in self.visited_realpaths {
            print(f"[CYCLE] already visited {here.real_path}");
            disengage;
        } else {
            self.visited_realpaths.append(here.real_path);
            self.checked += 1;
            if here.stale {
                self.stale_count += 1;
                print(f"[STALE] {here.real_path}");
            } else {
                self.clean += 1;
                print(f"[OK]    {here.real_path}");
            }
        }
    }

    can report with Root exit {
        print(
            f"Summary: {self.checked} skill(s) checked, "
            f"{self.clean} clean, {self.stale_count} stale, "
            f"{self.followed_links} symlink(s) followed"
        );
    }
}

