"""Demonstrate a history gate whose verdict changes with its resolved base."""

node Commit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sha: str = "";
    has order: int = 0;
    has checkpoint: bool = False;
}

node Gate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has base_label: str = "";
    has base_order: int = 0;
}

edge Scope { }
edge Parent { }

walker HistoryAuditor {
    has base_label: str = "";
    has base_order: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:Scope:->] else {
            disengage;
        }
    }

    can inspect with Gate entry {
        self.base_label = here.base_label;
        self.base_order = here.base_order;
        print(f"base={self.base_label}");
        visit [->:Scope:->] else {
            disengage;
        }
    }

    can inspect with Commit entry {
        if here.sha in self.seen {
            print(f"cycle detected at {here.sha}; stopping this history walk");
            disengage;
        } else {
            self.seen.append(here.sha);

            if here.order > self.base_order {
                if here.checkpoint {
                    print(f"  PASS {here.sha}: {here.title}");
                } else {
                    print(f"  VIOLATION {here.sha}: {here.title}");
                }
            }

            visit [->:Parent:->] else {
                disengage;
            }
        }
    }
}

