"""Simple-value graph conversion with explicit cycle detection.

Objects and arrays are connected through typed Contains edges. The converter
tracks the active recursion path, so recursive cycles are rejected while
shared acyclic subtrees remain convertible.
"""

node Simple {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has active: bool = False;
}

node SimpleObject(Simple) {
    has kind: str = "object";
}

node SimpleArray(Simple) {
    has kind: str = "array";
}

node Scalar(Simple) {
    has value: str = "";
}

edge Contains {
    has slot: int = 0;
}

walker Converter {
    has cycles: int = 0;
    has converted: int = 0;

    can start with Root entry {
        print("begin simple_to_json conversion");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with SimpleObject | SimpleArray entry {
        if here.active {
            self.cycles += 1;
            print(f"recursive structure detected at {here.title}");
            disengage;
        } else {
            here.active = True;
            self.converted += 1;
            print(f"converting {here.kind}: {here.title}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_scalar with Scalar entry {
        self.converted += 1;
        print(f"converting scalar: {here.value}");
    }

    can leave with SimpleObject | SimpleArray exit {
        here.active = False;
    }

    can report with Root exit {
        print(f"conversion complete: {self.converted} values, "
              f"{self.cycles} recursive structure(s)");
    }
}

with entry {
    shared = SimpleObject(title="shared-object");
    shared_leaf = Scalar(title="shared-leaf", value="reused");
    shared +>:Contains(slot=0):+> shared_leaf;

    safe = SimpleObject(title="acyclic-object");
    safe_left = SimpleArray(title="left-array");
    safe_right = SimpleArray(title="right-array");
    safe +>:Contains(slot=0):+> safe_left;
    safe +>:Contains(slot=1):+> safe_right;
