"""Dry-run cascade audit for workspace release tasks.

The initiating task is marked dry_run=True, while dependency tasks retain
their default False value, modeling the unsafe dependsOn cascade.
"""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ReleaseTask {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has dry_run: bool = False;
}

edge Contains {
    has relationship: str = "contains";
}

edge DependsOn {
    has relationship: str = "workspace dependency";
}

walker CascadeAuditor {
    has dry_run: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;
    has seen: list[str] = [];
    has unsafe_dependencies: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter_workspace with Workspace entry {
        print(f"workspace: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with ReleaseTask entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.depth += 1;

            if self.depth > self.max_depth {
                print(f"depth limit reached at {here.title}");
                disengage;
            } else {
                if self.dry_run and not here.dry_run {
                    self.unsafe_dependencies += 1;
                    print(f"UNSAFE: {here.title} runs with dry_run=False");
                } else {
                    mode = "dry-run" if here.dry_run else "real";
                    print(f"{here.title} scheduled in {mode} mode");
                }

                visit [->:DependsOn:->] else {
                    print(f"dependency walk complete at {here.title}");
                    disengage;
                }
            }
        }
    }
}

with entry {
    workspace = Workspace(
        title="release-workspace",
        year=2026,
        available=True
    );

    application = ReleaseTask(
        title="app:version",
        year=2026,
        available=True,
        dry_run=True
    );

    shared = ReleaseTask(
        title="shared:version",
        year=2026,
        available=True,
        dry_run=False
    );

    core = ReleaseTask(
        title="core:version",
        year=2026,
        available=True,
        dry_run=False
    );

    root +>:Contains(relationship="contains"):+> workspace;
    workspace +>:Contains(relationship="contains"):+> application;
    application +>:DependsOn(relationship="workspace dependency"):+> shared;
    shared +>:DependsOn(relationship="workspace dependency"):+> core;

    root spawn CascadeAuditor(dry_run=True);
}

"""Marlin MoE audit demo: equivalent token orderings produce the same expert total."""

node Batch {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Expert {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has expected_total: int = 0;
}

node Token {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has value: int = 0;
}

edge RoutedTo {
    has route_rank: int = 0;
}

edge Contains {
    has slot: int = 0;
}

walker MarlinAudit {
    has token_count: int = 0;
    has total: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_batch with Batch entry {
        print(f"Auditing {here.title}");
        visit [->:RoutedTo:->] else {
            disengage;
        }
    }

    can inspect_expert with Expert entry {
        self.token_count = 0;
        self.total = 0;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can accumulate with Token entry {
        self.token_count += 1;
        self.total += here.value;
    }

    can report with Expert exit {
        status = "STABLE" if self.total == here.expected_total else "ORDER-DEPENDENT";
        print(f"{here.title}: tokens={self.token_count}, total={self.total}, result={status}");
    }
}

with entry {
    batch = Batch(
        title="Marlin MoE batch",
        year=2026,
        available=True
    );

    first = Expert(
        title="expert-0 order [2, 7, 11]",
        year=2026,
        available=True,
        expected_total=20
    );

    second = Expert(
        title="expert-1 order [11, 2, 7]",
        year=2026,
        available=True,
        expected_total=20
    );

    root ++> batch;
    batch +>:RoutedTo(route_rank=0):+> first;
    batch +>:RoutedTo(route_rank=1):+> second;

    first_two = Token(
        title="token-2",
        year=2026,
        available=True,
        value=2
    );

    first_seven = Token(
        title="token-7",
        year=2026,
        available=True,
        value=7
    );

    first_eleven = Token(
        title="token-11",
        year=2026,
        available=True,
        value=11
    );

    first +>:Contains(slot=0):+> first_two;
    first +>:Contains(slot=1):+> first_seven;
    first +>:Contains(slot=2):+> first_eleven;

    second_eleven = Token(
        title="token-11",
        year=2026,
        available=True,
        value=11
    );

    second_two = Token(
        title="token-2",
        year=2026,
        available=True,
        value=2
    );

    second_seven = Token(
        title="token-7",
        year=2026,
        available=True,
        value=7
    );

    second +>:Contains(slot=0):+> second_eleven;
    second +>:Contains(slot=1):+> second_two;
    second +>:Contains(slot=2):+> second_seven;

    root spawn MarlinAudit();
}

