"""Native graph demo for atomic catalog refresh, model tombstones, and provider removal."""

node Provider {
    has provider_id: str = "";
    has lifecycle: str = "active";
    has credentials_present: bool = True;
    has admitted: int = 0;
    has is_default: bool = False;
    has diagnostic_bytes: int = 0;
    has last_diagnostic: str = "";
}

node Catalog {
    has provider_id: str = "";
    has generation: int = 0;
    has committed: bool = False;
    has current: bool = False;
}

node Model {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider_id: str = "";
    has model_id: str = "";
}

edge HasCatalog { }
edge ContainsModel { }
edge OwnsModel { }

walker CatalogRefresh {
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_provider with Provider entry {
        self.depth = self.depth + 1;
        print(f"refreshing provider {here.provider_id}");
        if self.depth < self.max_depth {
            visit [->:HasCatalog:->] else {
                disengage;
            }
        } else {
            print("refresh depth limit reached");
            disengage;
        }
    }

    can inspect_catalog with Catalog entry {
        if here.committed && here.current {
            print(f"using committed catalog generation {here.generation}");
            self.depth = self.depth + 1;
            if self.depth < self.max_depth {
                visit [->:ContainsModel:->] else {
                    disengage;
                }
            } else {
                print("catalog cycle guard stopped traversal");
                disengage;
            }
        } else {
            print(f"retaining non-current catalog generation {here.generation}");
            disengage;
        }
    }

    can reactivate with Model entry {
        if here.provider_id != "" && here.model_id != "" {
            here.available = True;
            print(f"exact model id {here.model_id} is available");
        }
    }
}

walker AdmissionGate {
    has depth: int = 0;
    has max_depth: int = 4;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can admit with Provider entry {
        self.depth = self.depth + 1;
        if here.lifecycle == "active" {
            here.admitted = here.admitted + 1;
            here.diagnostic_bytes = 22;
            here.last_diagnostic = "[secret redacted]";
            print(f"send admitted through {here.provider_id}");
        } else {
            print(f"send rejected immediately by {here.provider_id}");
        }
        if self.depth < self.max_depth {
            visit [->:HasCatalog:->] else {
                disengage;
            }
        } else {
            disengage;
        }
    }

    can observe with Catalog entry {
        print(f"admission observed catalog generation {here.generation}");
    }
}

walker RemovalCoordinator {
    has depth: int = 0;
    has max_depth: int = 8;
    has invalidate_models: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can reconcile with Provider entry {
        self.depth = self.depth + 1;
        if here.lifecycle == "removal_pending" && here.is_default {
            print(f"default provider guard retained {here.provider_id}");
            disengage;
        } else {
            if here.lifecycle == "removal_pending" && here.admitted == 0 {
                here.lifecycle = "tombstoned";
                here.credentials_present = False;
                self.invalidate_models = True;
                print(f"provider {here.provider_id} tombstoned after drain");
            } else {
                if here.lifecycle == "removal_pending" {
                    print(f"provider {here.provider_id} is draining {here.admitted} attempt(s)");
                }
                self.invalidate_models = False;
            }
            if self.depth < self.max_depth {
                visit [->:OwnsModel:->] else {
                    disengage;
                }
            } else {
                print("removal cycle guard stopped traversal");
                disengage;
            }
        }
    }

    can invalidate with Model entry {
        if self.invalidate_models {
            here.available = False;
            print(f"model {here.model_id} unavailable after provider removal");
        } else {
            print(f"model {here.model_id} retained its current availability");
        }
    }
}

with entry {
    default_provider = Provider(
        provider_id="default-provider",
        lifecycle="active",
        credentials_present=True,
        admitted=0,
        is_default=True,
        diagnostic_bytes=18,
