    retiring_provider +>:HasCatalog:+> old_snapshot;
    retiring_provider +>:HasCatalog:+> new_snapshot;

    new_snapshot +>:ContainsModel:+> exact_model;
    retiring_provider +>:OwnsModel:+> exact_model;
    retiring_provider +>:OwnsModel:+> missing_model;
    fallback_provider +>:OwnsModel:+> fallback_model;

    root spawn AdmissionGate();
    root spawn CatalogRefresh();
    root spawn RemovalCoordinator();
}

