"""Offline DEV evidence graph for selecting and freezing one R2 repair winner."""

node Candidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has structural_gain_bps: int = 0;
    has downstream_gain_bps: int = 0;
    has global_regression_bps: int = 0;
    has hallucination_delta: int = 0;
    has provider_attempts: int = 0;
    has reservations: int = 0;
    has cost: int = 0;
    has license_ok: bool = False;
    has resource_ok: bool = False;
    has failure_ok: bool = False;
    has dev_frozen: bool = False;
    has tie_rank: int = 0;

    def qualifies() -> bool {
        if not self.available {
            return False;
        }
        if self.structural_gain_bps < 500 {
            return False;
        }
        if self.downstream_gain_bps <= 0 {
            return False;
        }
        if self.global_regression_bps > 100 {
            return False;
        }
        if self.hallucination_delta != 0 {
            return False;
        }
        if self.provider_attempts != 0 {
            return False;
        }
        if self.reservations != 0 {
            return False;
        }
        if self.cost != 0 {
            return False;
        }
        if not self.license_ok {
            return False;
        }
        if not self.resource_ok {
            return False;
        }
        if not self.failure_ok {
            return False;
        }
        if not self.dev_frozen {
            return False;
        }
        return True;
    }
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
    has stable_gap_confirmed: bool = False;
    has downstream_confirmed: bool = False;
}

node Gate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has exact_boundary_tests: bool = False;
    has independent_recompute: bool = False;
    has holdout_denied: bool = False;
    has all_passed: bool = False;
}

edge HasEvidence {
    has bps: int = 0;
}

edge SubjectTo {
}

edge Rechecks {
}

walker WinnerSelector {
    has max_depth: int = 6;
    has depth: int = 0;
    has winner_title: str = "";
    has winner_gain: int = 0;
    has winner_rank: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_candidate with Candidate entry {
        if here.qualifies() {
            if self.winner_title == "" {
                self.winner_title = here.title;
                self.winner_gain = here.structural_gain_bps;
                self.winner_rank = here.tie_rank;
            } else {
                if here.structural_gain_bps > self.winner_gain {
                    self.winner_title = here.title;
                    self.winner_gain = here.structural_gain_bps;
                    self.winner_rank = here.tie_rank;
                } else {
                    if here.structural_gain_bps == self.winner_gain {
                        if here.tie_rank < self.winner_rank {
                            self.winner_title = here.title;
                            self.winner_gain = here.structural_gain_bps;
                            self.winner_rank = here.tie_rank;
                        }
                    }
                }
            }
        }

        if self.depth >= self.max_depth {
            print(f"Traversal depth cap reached at candidate {here.title}");
            disengage;
        } else {
            self.depth += 1;
            visit [->:HasEvidence:->] else {
                disengage;
            }
        }
    }

    can inspect_evidence with Evidence entry {
        print(f"Evidence accepted from {here.source}");
        if self.depth >= self.max_depth {
            print("Evidence traversal stopped by cycle-safety depth cap");
            disengage;
        } else {
            self.depth += 1;
            visit [->:SubjectTo:->] else {
                disengage;
            }
        }
    }

    can inspect_gate with Gate entry {
        if here.all_passed {
            print(f"Gate passed: {here.title}");
        } else {
            print(f"Gate failed: {here.title}");
        }

        if self.depth >= self.max_depth {
            print("Dependency traversal stopped by cycle-safety depth cap");
            disengage;
        } else {
            self.depth += 1;
            visit [->:Rechecks:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        if self.winner_title == "" {
            print("NO_REPAIR_ROUTE");
        } else {
            print(f"FROZEN_WINNER {self.winner_title} "
                  f"({self.winner_gain} bps structural gain)");
        }
    }
}

