"""Document move demo: rename a folder, reparent it, and update descendant paths."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: str = "";
    has slug: str = "";
    has path: str = "";
    has parent_path: str = "";
    has is_folder: bool = False;
}

edge Contains {
    has relation: str = "contains";
}

walker MoveDocuments {
    has source_path: str = "";
    has replacement_path: str = "";
    has source_parent: Document | None = None;
    has destination_parent: Document | None = None;
    has seen_ids: list[str] = [];
    has updated_count: int = 0;

    can begin with Root entry {
        print(f"Moving {self.source_path} to {self.replacement_path}");
        visit [->:Contains:->];
    }

    can enter_project with Project entry {
        visit [->:Contains:->];
    }

    can rewrite with Document entry {
        if here.id in self.seen_ids {
            print(f"cycle detected at {here.path}; stopping safely");
            disengage;
        } else {
            self.seen_ids.append(here.id);

            if here.path == self.source_path {
                if self.source_parent is not None {
                    self.source_parent del ->:Contains:-> here;
                }
                if self.destination_parent is not None {
                    self.destination_parent +>:Contains:+> here;
                }

                here.path = self.replacement_path;
                here.parent_path = self.destination_parent.path if self.destination_parent is not None else "";
                self.updated_count += 1;
                print(f"renamed and moved: {here.path}");
            } else {
                prefix = self.source_path + "/";
                if here.path.startswith(prefix) {
                    suffix = here.path[len(self.source_path):];
                    here.path = self.replacement_path + suffix;
                    here.parent_path = self.replacement_path + here.parent_path[len(self.source_path):];
                    self.updated_count += 1;
                    print(f"updated descendant: {here.path}");
                }
            }

            visit [->:Contains:->];
        }
    }
}

