            here.visited = True;
            here.execution_order_group = self.current_group;
            self.current_group += 1;

            print(
                f"{here.path}: group {here.execution_order_group}, "
                f"when_modified={here.when_modified}, "
                f"depends_on={here.depends_on}"
            );

            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }
}

