"""Native OSP demo for atomic catalog refresh, model tombstones, and provider removal."""

node Provider {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider_id: str = "";
    has lifecycle: str = "active";
    has credentials_present: bool = True;
    has admitted: int = 0;
    has is_default: bool = False;
    has successful_generation: int = 0;
    has diagnostic_bytes: int = 0;
    has last_diagnostic: str = "";
}

node Catalog {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider_id: str = "";
    has generation: int = 0;
    has committed: bool = False;
    has current: bool = False;
}

node Model {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider_id: str = "";
    has model_id: str = "";
    has last_seen_generation: int = 0;
}

edge HasCatalog {
    has relation: str = "snapshot";
}

edge ContainsModel {
    has relation: str = "catalog-member";
}

edge OwnsModel {
    has relation: str = "provider-model";
}

walker CatalogRefresh {
    has active_generation: int = 0;
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can refresh_provider with Provider entry {
        self.depth = self.depth + 1;

        if here.lifecycle == "active" {
            print(f"refreshing provider {here.provider_id}");
            if self.depth < self.max_depth {
                visit [->:HasCatalog:->] else {
                    disengage;
                }
            } else {
                print("refresh depth limit reached");
                disengage;
            }
        } else {
            print(f"refresh skipped for {here.provider_id}");
            disengage;
        }
    }

    can commit_snapshot with Catalog entry {
        if here.committed {
            if here.current {
                self.active_generation = here.generation;
                print(f"atomically committed catalog generation {here.generation}");
                visit [->:ContainsModel:->] else {
                    disengage;
                }
            } else {
                print(f"retaining older catalog generation {here.generation}");
                disengage;
            }
        } else {
            print("uncommitted catalog was not exposed");
            disengage;
        }
    }

    can reactivate_exact_model with Model entry {
        if here.last_seen_generation == 0 {
            here.available = True;
            here.last_seen_generation = self.active_generation;
            print(f"exact model id {here.model_id} reactivated");
        } else {
            print(f"model {here.model_id} already belongs to the committed snapshot");
        }
    }
}

walker TombstoneSweep {
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_provider with Provider entry {
        self.depth = self.depth + 1;

        if self.depth < self.max_depth {
            visit [->:OwnsModel:->] else {
                disengage;
            }
        } else {
            print("tombstone sweep depth limit reached");
            disengage;
        }
    }

    can mark_missing with Model entry {
        if here.last_seen_generation == 0 {
            here.available = False;
            print(f"model tombstone retained for missing id {here.model_id}");
        } else {
            print(f"model {here.model_id} remains available");
        }
    }
}

walker AdmissionGate {
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can admit with Provider entry {
        self.depth = self.depth + 1;

        if here.lifecycle == "active" {
            here.admitted = here.admitted + 1;
            here.diagnostic_bytes = 22;
            here.last_diagnostic = "[secret redacted]";
            print(f"send admitted through {here.provider_id}");
        } else {
            print(f"send rejected immediately by {here.provider_id}");
        }

        if self.depth < self.max_depth {
            visit [->:HasCatalog:->] else {
                disengage;
            }
        } else {
            disengage;
        }
    }

    can observe_catalog with Catalog entry {
        print(f"admission observed committed generation {here.generation}");
    }
}

walker RemovalCoordinator {
    has depth: int = 0;
    has max_depth: int = 8;
    has invalidate_models: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can reconcile with Provider entry {
        self.depth = self.depth + 1;

        if here.lifecycle == "removal_pending" {
            if here.is_default {
                print(f"default-provider guard retained {here.provider_id}");
                self.invalidate_models = False;
                disengage;
            } else {
                if here.admitted == 0 {
                    here.lifecycle = "tombstoned";
                    here.credentials_present = False;
                    self.invalidate_models = True;
                    print(f"provider {here.provider_id} tombstoned after drain");
                } else {
                    self.invalidate_models = False;
                    print(f"provider {here.provider_id} is draining");
                }
            }
        } else {
            self.invalidate_models = False;
            print(f"provider {here.provider_id} remains usable");
        }

        if self.depth < self.max_depth {
            visit [->:OwnsModel:->] else {
                disengage;
            }
        } else {
            print("removal reconciliation depth limit reached");
            disengage;
        }
    }

    can invalidate with Model entry {
        if self.invalidate_models {
            here.available = False;
            print(f"model {here.model_id} unavailable after provider removal");
        } else {
            print(f"model {here.model_id} retained during provider reconciliation");
        }
    }
}

