"""Native Jac demo of memoized recursive trust queries over a cyclic graph."""

node Person {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge TrustLink {
    has rule: str = "";
}

walker TrustQuery {
    has goal: str = "";
    has table: list[str] = [];
    has memo_hits: int = 0;
    has reached: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can explore with Person entry {
        if here.title in self.table {
            self.memo_hits += 1;
            disengage;
        } else {
            self.table.append(here.title);

            if here.title == self.goal {
                self.reached = True;
            }

            visit [->:TrustLink:->] else {
                disengage;
            }
        }
    }
}

