"""Artifact publication audit with typed lineage, validation gates, rollback, and bounded traversal."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has checksum: str = "";
    has config_ok: bool = True;
    has checksum_ok: bool = True;
    has accepted: bool = False;
    has status: str = "candidate";
}

node ValidationGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has config_ok: bool = True;
    has checksum_ok: bool = True;
    has passed: bool = False;
    has failure_stage: str = "";
}

edge Requires {
    has rationale: str = "";
}

edge Evaluates {
    has rationale: str = "";
}

walker ArtifactAuditor {
    has depth: int = 0;
    has max_depth: int = 4;

    can start with Root entry {
        print("starting artifact lineage audit");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Artifact entry {
        self.depth += 1;
        print(f"artifact {here.title} v{here.version} status={here.status}");

        if self.depth >= self.max_depth {
            print(f"depth limit reached at {here.title}; possible cycle rejected");
            here.accepted = False;
            here.available = False;
            here.status = "rejected-cycle-or-depth";
            disengage;
        }

        if here.config_ok and here.checksum_ok and here.available {
            here.accepted = True;
            here.status = "accepted";
            print(f"accepted {here.title}; source remains protected");
        } else {
            here.accepted = False;
            here.available = False;
            here.status = "rolled-back";
            print(f"rollback {here.title}; neighboring artifacts are untouched");
        }

        visit [->:Requires:->] else {
            disengage;
        }
    }

    can audit_gate with ValidationGate entry {
        self.depth += 1;
        print(f"gate {here.title}");

        if self.depth >= self.max_depth {
            print("gate traversal stopped by bounded cycle policy");
            disengage;
        }

        if here.config_ok and here.checksum_ok and here.available {
            here.passed = True;
            here.failure_stage = "";
            print("gate passed: promotion may proceed");
        } else {
            here.passed = False;

            if not here.config_ok {
                here.failure_stage = "malformed-config";
            } else {
                if not here.checksum_ok {
                    here.failure_stage = "checksum-mismatch";
                } else {
                    here.failure_stage = "unavailable-input";
                }
            }

            print(f"gate failed at {here.failure_stage}; last-known-good recovery selected");
        }

        visit [->:Evaluates:->] else {
            disengage;
        }
    }
}

