walker PipelineAuditor {
    has depth: int = 0;
    has max_depth: int = 7;

    can start with Root entry {
        print("Starting deployment pipeline audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_deployment with Deployment entry {
        if self.depth >= self.max_depth {
            print("Traversal depth limit reached at deployment");
            disengage;
