        print(f"{here.title}: {here.status}");
        visit [->:DeploymentWorkflow:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        if self.depth >= self.max_depth {
            print("Traversal depth limit reached at workflow");
            disengage;
        }

        self.depth += 1;
        print(f"Workflow reached: {here.workflow_name}");
        visit [->:WorkflowBuild:->] else {
            disengage;
        }
    }

    can inspect_build with Build entry {
        if self.depth >= self.max_depth {
            print("Traversal depth limit reached at build");
            disengage;
        }

        self.depth += 1;
        print(f"Build artifact reached: {here.artifact}");
        visit [->:BuildCommit:->] else {
            disengage;
        }
    }

    can inspect_commit with Commit entry {
        if self.depth >= self.max_depth {
            print(f"Cycle guard stopped traversal at commit {here.commit_hash}");
            disengage;
        }

        self.depth += 1;
        print(f"Auditing commit {here.commit_hash}: {here.title}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

