"""SwiftPM dependency identity and cycle-resolution demo.

Packages expose one canonical identity chosen from an explicit identity or a
kind-specific derived identity. Typed dependency edges replace adjacency
plumbing, while a walker preserves cycle detection during resolution.
"""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has explicit_identity: str = "";
    has derived_identity: str = "";
    has source_kind: str = "source-control";

    def resolution_identity() -> str {
        identity = self.explicit_identity if self.explicit_identity != "" else self.derived_identity;
        return identity;
    }
}

edge Contains { }

edge DependsOn {
    has requirement_name: str = "";
}

walker DependencyResolver {
    has visited: list[str] = [];
    has resolution_order: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can resolve with Package entry {
        identity = here.resolution_identity();

        if identity in self.visited {
            self.cycle_detected = True;
            print(f"cycle detected at package identity '{identity}'");
        } else {
            self.visited.append(identity);
            self.resolution_order.append(identity);
            print(f"resolving {identity} from {here.source_kind}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"resolved package count: {len(self.resolution_order)}");
        print(f"cycle detected: {self.cycle_detected}");
    }
}

with entry {
    app = Package(
        title="ExampleApp",
        explicit_identity="",
        derived_identity="example-app",
        source_kind="source-control"
    );

    support = Package(
        title="SwiftToolsSupport",
        explicit_identity="swift-tools-support",
        derived_identity="swift-tools-support.git",
        source_kind="registry"
    );

    logging = Package(
        title="Logging",
        explicit_identity="",
        derived_identity="logging",
        source_kind="source-control"
    );

    root +>:Contains:+> app;

    app +>:DependsOn(requirement_name="swift-tools-support"):+> support;
    support +>:DependsOn(requirement_name="logging"):+> logging;
    logging +>:DependsOn(requirement_name="swift-tools-support"):+> support;

    root spawn DependencyResolver();
}

