    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has commit: str = "";
    has status: str = "pending";
}

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version_code: int = 0;
    has deployed: bool = False;
}

edge Contains { }
edge DependsOn { }
edge Produces { }
edge Deploys { }

walker DeploymentAuditor {
    has seen: list[str] = [];

    can begin with Root entry {
        print("Auditing deployment pipeline");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        if here.version_code == here.store_version_code {
            print(f"ERROR: {here.title} uses versionCode "
                  f"{here.version_code}, already present on Google Play");
        } else {
            print(f"OK: {here.title} can use versionCode "
                  f"{here.version_code}");
        }
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_build with Build entry {
        if here.title in self.seen {
            print(f"CYCLE DETECTED at build {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            print(f"Build {here.title}: {here.status} "
                  f"(commit {here.commit})");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

walker ReleaseAuditor {
    can begin with Root entry {
        visit [->:Deploys:->] else {
            disengage;
        }
    }

    can inspect with Release entry {
        if here.deployed {
            print(f"Release {here.title} versionCode "
                  f"{here.version_code} is deployed");
        } else {
            print(f"Release {here.title} versionCode "
                  f"{here.version_code} is awaiting deployment");
        }
    }
}

