    );

    root +>:Contains:+> workflow;
    workflow +>:Contains:+> build_a;
    workflow +>:Contains:+> build_b;
    build_a +>:DependsOn:+> build_b;
    build_b +>:DependsOn:+> build_a;
    build_a +>:Produces:+> release;
    workflow +>:Deploys:+> release;

    root spawn DeploymentAuditor();
    root spawn ReleaseAuditor();
}

