"""SwiftPM dependency identity resolution with typed dependency edges and cycle detection."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has explicit_identity: str = "";
    has derived_identity: str = "";
    has registry_identity: str = "";
    has source_kind: str = "source-control";

    def resolution_identity(use_registry_identity: bool) -> str {
        if use_registry_identity and self.registry_identity != "" {
            return self.registry_identity;
        }
        if self.explicit_identity != "" {
            return self.explicit_identity;
        }
        return self.derived_identity;
    }
}

edge Contains { }

edge DependsOn {
    has requirement_name: str = "";
}

walker DependencyResolver {
    has use_registry_identity: bool = False;
    has visited: list[str] = [];
    has resolution_order: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("Resolving package dependencies");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can resolve with Package entry {
        identity = here.resolution_identity(self.use_registry_identity);

        if identity in self.visited {
            self.cycle_detected = True;
            print(f"cycle detected at {identity}");
        } else {
            self.visited.append(identity);
            self.resolution_order.append(identity);
            status = "available" if here.available else "unavailable";
            print(f"resolved {identity} ({here.source_kind}, {status})");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        count = len(self.resolution_order);
        cycle_label = "yes" if self.cycle_detected else "no";
        print(f"resolution order contains {count} package(s); cycle: {cycle_label}");
    }
}

