"""Build-from-spec demo: traverse task dependencies, unblock integrated work, and detect cycles."""

node Spec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has spec_id: str = "";
    has repo: str = "";
    has state: str = "Blocked";
    has blocked: bool = True;
    has dependency_count: int = 0;
    has integrated: bool = False;
}

edge Contains {
    has relationship: str = "spec-task";
}

edge Dependency {
    has same_repo: bool = True;
    has relationship: str = "must-complete-before";
}

walker DependencyPlanner {
    has seen_titles: list[str] = [];
    has integrated_repo: str = "";

    can start with Root entry {
        print("Starting build-from-spec planning");
        visit [-->] else {
            disengage;
        }
    }

    can expand with Spec entry {
        print(f"Spec: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can plan with Task entry {
        if here.title in self.seen_titles {
            print(f"Cycle detected at task '{here.title}'");
            disengage;
        } else {
            self.seen_titles.append(here.title);

            if here.blocked {
                if self.integrated_repo == here.repo {
                    here.blocked = False;
                    here.state = "Ready";
                    print(f"Unblocked: {here.title} from integrated repo {here.repo}");
                } else {
                    print(f"Blocked: {here.title} waits for repo {here.repo}");
                }
            }

            if not here.blocked {
                if here.state != "Done" {
                    here.state = "Done";
                    print(f"Completed: {here.title}");
                }

                if here.integrated {
                    self.integrated_repo = here.repo;
                    print(f"Integrated: {here.title} into {here.repo}");
                }
            }

            visit [->:Dependency:->] else {
                disengage;
            }
        }
    }
}

