"""Retained-mode UI demo with typed tree and dependency edges.

The layout walker replaces recursive child traversal, while the invalidation
walker follows dependency edges and explicitly stops on cycles.
"""

node UiElement {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has min_width: int = 0;
    has min_height: int = 0;
    has measured_width: int = 0;
    has measured_height: int = 0;
    has layout_dirty: bool = True;
    has paint_dirty: bool = True;
    has focused: bool = False;
    has hovered: bool = False;
    has pressed: bool = False;
}

node Panel(UiElement) {
    has padding: int = 0;
}

node Control(UiElement) {
    has label: str = "";
}

node TextBlock(UiElement) {
    has text: str = "";
}

edge Child {
    has slot: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker LayoutWalker {
    has seen: list[str] = [];

    can start with Root entry {
        self.seen = [];
        visit [->:Child:->] else {
            disengage;
        }
    }

    can measure with UiElement entry {
        if here.key in self.seen {
            print(f"layout cycle or duplicate ignored at {here.key}");
            disengage;
        } else {
            self.seen = self.seen + [here.key];

            if here.layout_dirty {
                here.measured_width = here.min_width;
                here.measured_height = here.min_height;
                here.layout_dirty = False;
                here.paint_dirty = True;
                print(f"measured {here.key}: "
                      f"{here.measured_width}x{here.measured_height}");
            }

            visit [->:Child:->] else {
                disengage;
            }
        }
    }
}

walker InvalidationWalker {
    has seen: list[str] = [];

    can start with Root entry {
        self.seen = [];
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can propagate with UiElement entry {
        if here.key in self.seen {
            print(f"invalidation cycle detected at {here.key}");
            disengage;
        } else {
            self.seen = self.seen + [here.key];

            if here.layout_dirty {
                here.paint_dirty = True;
                print(f"invalidated paint for {here.key}");
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

walker PaintWalker {
    can start with Root entry {
        visit [->:Child:->] else {
            disengage;
        }
    }

    can rebuild with UiElement entry {
        if here.paint_dirty {
            here.paint_dirty = False;
            print(f"rebuilt retained draw list for {here.key}");
        }

        visit [->:Child:->] else {
            disengage;
        }
    }
}

