    has id: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Part {
    has id: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has category_id: int = 0;
}

node RecursiveRequest {
    has id: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has root_category_id: int = 0;
}

edge StartsAt {
}

edge ChildCategory {
    has relation: str = "";
}

edge Contains {
    has relation: str = "";
}

walker RecursiveResolver {
    has visited_categories: list[int] = [];
    has matching_parts: list[int] = [];

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can resolve_request with RecursiveRequest entry {
        print(f"starting recursive resolution at category {here.root_category_id}");
        visit [-->] else {
            disengage;
        }
    }

    can descend with PartCategory entry {
        if here.id in self.visited_categories {
            print(f"cycle detected at category {here.id}; stopping this walk");
            disengage;
        } else {
            self.visited_categories.append(here.id);
            print(f"visiting category {here.id}: {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }

    can collect with Part entry {
        self.matching_parts.append(here.id);
        print(f"matched part {here.id}: {here.title}");
    }

    can report with Root exit {
        print(f"recursive resolution found {len(self.matching_parts)} parts");
    }
}

