    has available: bool = True;
    has id: int = 0;
    has parent_id: int = 0;
}

node Part {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: int = 0;
    has category_id: int = 0;
}

node RecursiveQuery {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has id: int = 0;
    has root_category_id: int = 0;
}

edge StartsAt {
    has relation: str = "";
}

edge Expansion {
    has relation: str = "";
}

walker RecursiveResolver {
    has visited_categories: list[int] = [];
    has matching_parts: list[int] = [];

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can resolve with RecursiveQuery entry {
        print(f"starting recursive lookup at category {here.root_category_id}");
        visit [->:StartsAt:->] else {
            disengage;
        }
    }

    can expand with PartCategory entry {
        if here.id in self.visited_categories {
            print(f"cycle detected at category {here.id}");
            disengage;
        } else {
            self.visited_categories.append(here.id);
            print(f"visiting category {here.id}: {here.title}");
            visit [->:Expansion:->] else {
                disengage;
            }
        }
    }

    can collect with Part entry {
        if here.available {
            self.matching_parts.append(here.id);
            print(f"matched available part {here.id}: {here.title}");
        }
    }

    can report with Root exit {
        print(f"recursive lookup found {len(self.matching_parts)} available parts");
    }
}

