    );

    root ++> request;
    request +>:StartsAt(relation="recursive category seed"):+> electronics;

    electronics +>:Expansion(relation="child category"):+> computers;
    computers +>:Expansion(relation="child category"):+> laptops;
    computers +>:Expansion(relation="child category"):+> accessories;

    laptops +>:Expansion(relation="category membership"):+> processor;
    accessories +>:Expansion(relation="category membership"):+> keyboard;
    computers +>:Expansion(relation="category membership"):+> display;

    accessories +>:Expansion(relation="cycle probe"):+> electronics;

    root spawn RecursiveResolver();
}

"""Certificate-closure demo with typed graph edges, a cycle gate, and a
load-bearing visited set for repeated certifier/issuer pairs under different
certified keys.
"""

node Principal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node CertificationRule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has certifier: str = "";
    has issuer: str = "";
    has certified_key: str = "";
    has issuer_holds_key: bool = False;
}

edge Issues {
    has relation: str = "";
}

edge Targets {
    has relation: str = "";
}

walker ClosureAuditor {
    has seen_pairs: list[str] = [];
    has fired: int = 0;

    can start with Root entry {
        print("starting certificate closure");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Principal entry {
        print(f"checking principal {here.title}");
        visit [->:Issues:->] else {
            disengage;
        }
    }

    can evaluate with CertificationRule entry {
        pair = f"{here.certifier}->{here.issuer}";

        if here.issuer_holds_key == True {
            print(f"GATE 1 rejected {pair} for key {here.certified_key}");
        } else {
            if pair in self.seen_pairs {
                print(f"visited-set rejected {pair} for second key {here.certified_key}");
            } else {
                self.seen_pairs.append(pair);
                self.fired += 1;
                print(f"fired {pair} for key {here.certified_key}");
                visit [->:Targets:->] else {
                    disengage;
                }
            }
        }
    }
}

with entry {
    alice = Principal(title="Alice");
    bob = Principal(title="Bob");

    rule_ab_primary = CertificationRule(
        title="Alice certifies Bob with K1",
        certifier="Alice",
        issuer="Bob",
        certified_key="K1",
        issuer_holds_key=False
    );
    rule_ab_second_key = CertificationRule(
        title="Alice certifies Bob with K2",
        certifier="Alice",
        issuer="Bob",
        certified_key="K2",
        issuer_holds_key=False
    );
    rule_ba = CertificationRule(
        title="Bob certifies Alice with K3",
        certifier="Bob",
        issuer="Alice",
        certified_key="K3",
        issuer_holds_key=False
    );

    root ++> alice;

    alice +>:Issues(relation="certificate rule"):+> rule_ab_primary;
    alice +>:Issues(relation="certificate rule"):+> rule_ab_second_key;
    bob +>:Issues(relation="certificate rule"):+> rule_ba;

    rule_ab_primary +>:Targets(relation="certified issuer"):+> bob;
    rule_ab_second_key +>:Targets(relation="certified issuer"):+> bob;
    rule_ba +>:Targets(relation="certified issuer"):+> alice;

    auditor = ClosureAuditor();
    root spawn auditor;

    print(f"closure rules fired: {auditor.fired}");
}

