"""Certificate-closure demo using typed certificate relationships and an explicit
cycle gate. Each rule may fire once; revisiting a fired rule is rejected by the
gate, preventing the closure walk from looping indefinitely.
"""

node Principal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has held_key: str = "";
}

node CertificationRule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has certifier: str = "";
    has issuer: str = "";
    has certified_key: str = "";
    has cycle_gate: bool = False;
}

edge Issues {
    has relation: str = "";
}

edge Targets {
    has relation: str = "";
}

walker ClosureAuditor {
    has fired: int = 0;

    can start with Root entry {
        print("starting certificate closure");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Principal entry {
        print(f"checking principal {here.title}");
        visit [->:Issues:->] else {
            disengage;
        }
    }

    can evaluate with CertificationRule entry {
        token = f"{here.certifier}|{here.issuer}|{here.certified_key}";

        if here.cycle_gate {
            print(f"GATE 1 rejected repeated {token}");
            disengage;
        } else {
            here.cycle_gate = True;
            self.fired += 1;
            print(f"fired {token}");
            visit [->:Targets:->] else {
                disengage;
            }
        }
    }
}

with entry {
    alice = Principal(title="Alice", held_key="K1");
    bob = Principal(title="Bob", held_key="K2");

    primary = CertificationRule(
        title="Alice certifies Bob with K1",
        certifier="Alice",
        issuer="Bob",
        certified_key="K1"
    );

    alternate = CertificationRule(
        title="Alice certifies Bob with K2",
        certifier="Alice",
        issuer="Bob",
        certified_key="K2"
    );

    return_rule = CertificationRule(
        title="Bob certifies Alice with K3",
        certifier="Bob",
        issuer="Alice",
        certified_key="K3"
    );

    root ++> alice;
    alice +>:Issues(relation="certificate"):+> primary;
    alice +>:Issues(relation="certificate"):+> alternate;
    bob +>:Issues(relation="certificate"):+> return_rule;

    primary +>:Targets(relation="certified issuer"):+> bob;
    alternate +>:Targets(relation="certified issuer"):+> bob;
    return_rule +>:Targets(relation="certified issuer"):+> alice;

    auditor = ClosureAuditor();
    root spawn auditor;

    print(f"rules fired before cycle gates closed: {auditor.fired}");
}
